`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (sign-off). Reference: golden/reference (depack__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg [31:0] flit;
  wire wr_clk = tb_clk;
  reg reset;
  wire [31:0] data_out; wire [31:0] ref_data_out;
  wire [0:0] wr_en; wire [0:0] ref_wr_en;
  wire [0:0] c_rd; wire [0:0] ref_c_rd;
  depack dut (.flit(flit), .wr_clk(wr_clk), .reset(reset), .data_out(data_out), .wr_en(wr_en), .c_rd(c_rd));
  depack__ref ref_i (.flit(flit), .wr_clk(wr_clk), .reset(reset), .data_out(ref_data_out), .wr_en(ref_wr_en), .c_rd(ref_c_rd));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1)
      if (ref_data_out[tb_b] !== 1'bx && ref_data_out[tb_b] !== 1'bz && data_out[tb_b] !== ref_data_out[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 32;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: data_out = %h, expected %h", $time, tb_cyc, data_out, ref_data_out);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_wr_en[tb_b] !== 1'bx && ref_wr_en[tb_b] !== 1'bz && wr_en[tb_b] !== ref_wr_en[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: wr_en = %h, expected %h", $time, tb_cyc, wr_en, ref_wr_en);
      end
  end endtask
  task tb_props; begin
  end endtask
  reg [31:0] tbc_p_data_out, tbc_t_data_out;
  reg [0:0] tbc_p_wr_en, tbc_t_wr_en;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_data_out = tbc_t_data_out | ((ref_data_out ^ tbc_p_data_out) & ~(ref_data_out ^ ref_data_out)); tbc_p_data_out = ref_data_out;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_wr_en = tbc_t_wr_en | ((ref_wr_en ^ tbc_p_wr_en) & ~(ref_wr_en ^ ref_wr_en)); tbc_p_wr_en = ref_wr_en;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_data_out) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 32; tb_b = tb_b + 1) if (tbc_t_data_out[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_wr_en) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_wr_en[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 2 checked outputs toggled, %0d of 33 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 29; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    flit = 0; reset = 0; reset = 1;
    tbc_t_data_out = 0; tbc_p_data_out = 0; tbc_t_wr_en = 0; tbc_p_wr_en = 0;
    for (tb_cyc = 0; tb_cyc < 5000; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      flit = {tb_rand(0)};
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 40 == 0);
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
`timescale 1ns / 1ps



















module depack__ref(
input [31:0] flit,
input wr_clk,
input reset,
output reg [31:0]data_out,
output reg wr_en,c_rd

    );
reg [15:0]data1;
parameter state0=0,header=1,firsthalf=2,secondhalf=3,nextstate=4;
reg [2:0] currentstate;
integer i;



always@(posedge wr_clk)
begin
if(reset==1'b1)
begin
currentstate=state0;
wr_en=0;
i=0;
end
else
begin

case(currentstate)
state0:
begin
if({flit[30],flit[29]}==2'b01)
begin 
wr_en=0;
currentstate=header;
end
else
begin
currentstate=state0;
data_out=data_out;
wr_en=0;
end
end


header:
begin
if({flit[30],flit[29]}==2'b00)
begin
wr_en=0;
data1=flit[15:0];
 currentstate=firsthalf;
end
else
currentstate=header;
end


firsthalf:
begin
if({flit[30],flit[29]}==2'b10)
begin
currentstate=state0;
wr_en=0;
end
else
begin
wr_en=1;
c_rd=1;
data_out={flit[15:0],data1};
currentstate=header;
end
end 

default:
currentstate=state0;

endcase
end
end

endmodule
